  });
});

function checkWinner(board, row, col) {
  const color = board[row][col];
  if (!color) return null;

  // Check horizontal
  let count = 1;
  let c = col - 1;
  while (c >= 0 && board[row][c] === color) {
    count++;
    c--;
  }
  c = col + 1;
  while (c < 7 && board[row][c] === color) {
    count++;
    c++;
  }
  if (count >= 4) return color;

  // Check vertical
  count = 1;
  let r = row - 1;
  while (r >= 0 && board[r][col] === color) {
    count++;
    r--;
  }
  r = row + 1;
  while (r < 6 && board[r][col] === color) {
    count++;
    r++;
  }
  if (count >= 4) return color;

  // Check diagonal (top-left to bottom-right)
  count = 1;
  r = row - 1;
  c = col - 1;
  while (r >= 0 && c >= 0 && board[r][c] === color) {
    count++;
    r--;
    c--;
  }
  r = row + 1;
  c = col + 1;
  while (r < 6 && c < 7 && board[r][c] === color) {
    count++;
    r++;
    c++;
  }
  if (count >= 4) return color;

  // Check diagonal (top-right to bottom-left)
  count = 1;
  r = row - 1;
  c = col + 1;
  while (r >= 0 && c < 7 && board[r][c] === color) {
    count++;
    r--;
    c++;
  }
  r = row + 1;
  c = col - 1;
  while (r < 6 && c >= 0 && board[r][c] === color) {
    count++;
    r++;
    c--;
  }
  if (count >= 4) return color;

  return null;
}

function findWinningCells(board, row, col, color) {
  const cells = [];

  // Horizontal
  let count = 1;
  let cells_h = [[row, col]];
  let c = col - 1;
  while (c >= 0 && board[row][c] === color) {
    cells_h.push([row, c]);
    count++;
    c--;
  }
  c = col + 1;
  while (c < 7 && board[row][c] === color) {
    cells_h.push([row, c]);
    count++;
    c++;
  }
  if (count >= 4) return cells_h;

  // Vertical
  count = 1;
  let cells_v = [[row, col]];
  let r = row - 1;
  while (r >= 0 && board[r][col] === color) {
    cells_v.push([r, col]);
    count++;
    r--;
  }
  r = row + 1;
  while (r < 6 && board[r][col] === color) {
    cells_v.push([r, col]);
    count++;
    r++;
  }
  if (count >= 4) return cells_v;

  // Diagonal (top-left to bottom-right)
  count = 1;
  let cells_d1 = [[row, col]];
  r = row - 1;
  c = col - 1;
  while (r >= 0 && c >= 0 && board[r][c] === color) {
    cells_d1.push([r, c]);
    count++;
    r--;
    c--;
  }
  r = row + 1;
  c = col + 1;
  while (r < 6 && c < 7 && board[r][c] === color) {
    cells_d1.push([r, c]);
    count++;
    r++;
    c++;
  }
  if (count >= 4) return cells_d1;

  // Diagonal (top-right to bottom-left)
  count = 1;
  let cells_d2 = [[row, col]];
  r = row - 1;
  c = col + 1;
  while (r >= 0 && c < 7 && board[r][c] === color) {
    cells_d2.push([r, c]);
    count++;
    r--;
    c++;
  }
  r = row + 1;
  c = col - 1;
  while (r < 6 && c >= 0 && board[r][c] === color) {
    cells_d2.push([r, c]);
    count++;
    r++;
    c--;
  }
  if (count >= 4) return cells_d2;

  return [];
}

function recalculateScores(gameState, gameId, allMoves) {
  // This is called after undo/redo to ensure scores are accurate
  // Count wins by replaying the game
  const appliedMoves = gameState.applied_moves;
  const board = Array(6).fill(null).map(() => Array(7).fill(null));

  let redWins = 0;
  let yellowWins = 0;
  let draws = 0;

  for (const moveNum of appliedMoves) {
    const move = allMoves.find(m => m.move_number === moveNum);
    const row = move.landing_row - 1;
    const col = move.column - 1;
    board[row][col] = move.color;

    const winner = checkWinner(board, row, col);
    if (winner === 'Red') {
      redWins++;
      // Clear board for next round
      board.fill(null);
      board.forEach((r, i) => board[i] = Array(7).fill(null));
    } else if (winner === 'Yellow') {
      yellowWins++;
      // Clear board for next round
      board.fill(null);
      board.forEach((r, i) => board[i] = Array(7).fill(null));
    }
  }

  // Check for draw in current round
  if (appliedMoves.length === 42 || 
      (appliedMoves.length > 0 && !checkWinner(board, allMoves.find(m => m.move_number === appliedMoves[appliedMoves.length - 1]).landing_row - 1, allMoves.find(m => m.move_number === appliedMoves[appliedMoves.length - 1]).column - 1))) {
    if (appliedMoves.length === 42) {
      draws++;
    }
  }

  gameState.red_wins = redWins;
  gameState.yellow_wins = yellowWins;
  gameState.draws = draws;
}

